vec3 tone(vec3 color){	
	mat3 m1 = mat3(
        0.59719, 0.07600, 0.02840,
        0.35458, 0.90834, 0.13383,
        0.04823, 0.01566, 0.83777
	);
	mat3 m2 = mat3(
        1.60475, -0.10208, -0.00327,
        -0.53108,  1.10813, -0.07276,
        -0.07367, -0.00605,  1.07602
	);
	vec3 v = m1 * color;    
	vec3 a = v * (v + 0.0245786) - 0.000090537;
	vec3 b = v * (0.983729 * v + 0.4329510) + 0.238081;
	return pow(clamp(m2 * (a / b), 0.0, 1.0), vec3(1.0 / 2.2));
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
    vec2 uv = (fragCoord.xy / iResolution.xy);

    vec4 col = texture(iChannel0, uv);

    col.rgb /= col.w;
    col.rgb = tone(col.rgb);
    //col.rgb -= 0.4;
    //col.rgb *= 10.0;

	fragColor = col;
}

const float pi = 3.141592653558979323;

struct info {
    float dist;
    vec3 norm;
    vec3 alb;
    vec3 emissive;
};

bool iSphere(in vec3 ro, in vec3 rd, inout info hit, in vec4 sph) {
	vec3 m = ro - sph.xyz;

	float b = dot(m, rd);

	float c = dot(m, m) - sph.w * sph.w;

	if(c > 0.0 && b > 0.0)
		return false;

	float discr = b * b - c;

	if(discr < 0.0)
		return false;

    bool inside = false;
	float dist = -b - sqrt(discr);
    if (dist < 0.0) {
        inside = true;
        dist = -b + sqrt(discr);
    }

	if (dist < hit.dist) {
        hit.dist = dist;        
        hit.norm = normalize((ro+rd*dist) - sph.xyz) * (inside ? -1.0 : 1.0);
        return true;
    }

    return false;
}

uint hash(inout uint seed)
{
    seed = uint(seed ^ uint(61)) ^ uint(seed >> uint(16));
    seed *= uint(9);
    seed = seed ^ (seed >> 4);
    seed *= uint(0x27d4eb2d);
    seed = seed ^ (seed >> 15);
    return seed;
}

float randF(inout uint state)
{
    return float(hash(state)) / 4294967296.0;
}

vec3 randV(inout uint state)
{
    float z = randF(state) * 2.0 - 1.0;
    float a = randF(state) * 3.14159265358979323 * 2.0;
    float r = sqrt(1.0f - z * z);
    float x = r * cos(a);
    float y = r * sin(a);
    return vec3(x, y, z);
}

vec3 hemiDir (vec3 norm, inout uint rand) {
    vec3 dir = randV(rand);
    return dir * sign(dot(norm, dir));
}

vec3 cosineDir (vec3 norm, inout uint rand) {
    return normalize(norm + randV(rand));
}

// ---- QUATERNIONS ----

vec4 quaternionMultiply(vec4 a, vec4 b) {
    return vec4(
        a.x * b.w + a.y * b.z - a.z * b.y + a.w * b.x,
        -a.x * b.z + a.y * b.w + a.z * b.x + a.w * b.y,
        a.x * b.y - a.y * b.x + a.z * b.w + a.w * b.z,
        -a.x * b.x - a.y * b.y - a.z * b.z + a.w * b.w
    );
}

vec3 quaternionRotate(vec3 pos, vec4 q) {
    vec4 qInv = vec4(-q.xyz, q.w);
    return quaternionMultiply(quaternionMultiply(q, vec4(pos, 0)), qInv).xyz;
}

vec4 getRotationToZAxis(vec3 vec) {

	// Handle special case when input is exact or near opposite of (0, 0, 1)
	if (vec.z < -0.99999f) return vec4(1.0f, 0.0f, 0.0f, 0.0f);

	return normalize(vec4(vec.y, -vec.x, 0.0f, 1.0f + vec.z));
}

vec3 n_min (vec3 r) {
    return (1.0 - r) / (1.0 + r);
}

vec3 n_max (vec3 r) {
    return (1.0 + sqrt(r)) / (1.0 - sqrt(r));
}

vec3 get_n (vec3 r, vec3 g) {
    return n_min(r) * g + (1.0 - g) * n_max(r);
}

vec3 get_k2 (vec3 r, vec3 n) {
    vec3 nr = (n + 1.0) * (n + 1.0) * r - (n - 1.0) * (n - 1.0);
    return nr / (1.0 - r);
}

vec3 get_r (vec3 n, vec3 k) {
    return ((n - 1.0) * (n - 1.0) + k * k) / ((n + 1.0) * (n + 1.0) + k * k);
}

vec3 get_g (vec3 n, vec3 k) {
    vec3 r = get_r(n, k);
    return (n_max(r) - n) / (n_max(r) - n_min(r));
}

vec3 fresnel (vec3 r, vec3 g, float c) {
    if (r == vec3(1.0)) return vec3(1.0);
    vec3 r2 = clamp(r, 0.0, 0.999999);

    vec3 n = get_n(r2, g);
    vec3 k2 = get_k2(r2, n);

    vec3 rs_num = n * n + k2 - 2.0 * n * c + c * c;
    vec3 rs_den = n * n + k2 + 2.0 * n * c + c * c;
    vec3 rs = rs_num / rs_den;

    vec3 rp_num = (n * n + k2) * c * c - 2.0 * n * c + 1.0;
    vec3 rp_den = (n * n + k2) * c * c + 2.0 * n * c + 1.0;
    vec3 rp = rp_num / rp_den;

    return (rp + rs) / 2.0;
}

float distributionGGX(vec3 v, float alpha) {
    float alpha2 = alpha * alpha;
    return 1.0 / (pi * alpha2 * pow(v.x * v.x / alpha2 + v.y * v.y / alpha2 + v.z * v.z , 2.0));
}

float smithShadowing(vec3 v, float roughness) {
    float lambda = (-1.0 + sqrt(1.0 + (roughness * roughness * (v.x * v.x + v.y * v.y)) / v.z / v.z)) / 2.0;
    return 1.0 / (1.0 + lambda);
}

float smithUncorrelatedGeometry(vec3 V, vec3 L, float roughness) {
    return smithShadowing(V, roughness) * smithShadowing(L, roughness);
}

vec3 sampleGGXVNDF(vec3 Ve, vec2 alpha2D, vec2 u) {
	vec3 Vh = normalize(vec3(alpha2D.x * Ve.x, alpha2D.y * Ve.y, Ve.z));

	float lensq = Vh.x * Vh.x + Vh.y * Vh.y;
	vec3 T1 = lensq > 0.0f ? vec3(-Vh.y, Vh.x, 0.0f) * inversesqrt(lensq) : vec3(1.0f, 0.0f, 0.0f);
	vec3 T2 = cross(Vh, T1);

	float r = sqrt(u.x);
	float phi = 2.0 * pi * u.y;
	float t1 = r * cos(phi);
	float t2 = r * sin(phi);
	float s = 0.5f * (1.0f + Vh.z);
	t2 = mix(sqrt(1.0f - t1 * t1), t2, s);

	vec3 Nh = t1 * T1 + t2 * T2 + sqrt(max(0.0f, 1.0f - t1 * t1 - t2 * t2)) * Vh;

	return normalize(vec3(alpha2D.x * Nh.x, alpha2D.y * Nh.y, max(0.0f, Nh.z)));
}

vec3 brdf (vec3 alb, float rough, float metal, vec3 r, vec3 g, vec3 normal, vec3 view, vec3 light) {
    vec4 q = getRotationToZAxis(normal);
    vec3 V = quaternionRotate(view, q);
    vec3 L = quaternionRotate(light, q);
    vec3 H = normalize(V + L);

    float HdotV = clamp(dot(H, V), 0.0, 1.0);
    float NdotH = clamp(H.z, 0.0, 1.0);

    vec3 F = fresnel(r, g, HdotV);
    float D = distributionGGX(H, rough);
    float G = smithUncorrelatedGeometry(V, L, rough);

    vec3 spec = F * D * G / max(4.0 * V.z * L.z, 0.001);

    if (rough == 0.0) return (1.0 - metal) * (1.0 - fresnel(r, g, max(dot(normal, view), 0.0))) * alb / pi * max(L.z, 0.0);
    return ((1.0 - metal) * (1.0 - fresnel(r, g, max(dot(normal, view), 0.0))) * alb / pi + spec) * L.z;
}

vec3 sampleSpecular(vec3 alb, float rough, float metal, vec3 r, vec3 g, vec3 normal, vec3 view, inout uint rng, out vec3 brdf) {
    vec4 q = getRotationToZAxis(normal);
    vec3 V = quaternionRotate(view, q);
    vec3 H = sampleGGXVNDF(V, vec2(rough), vec2(randF(rng), randF(rng)));
    vec3 L = reflect(-V, H);


    vec3 F = fresnel(r, g, max(dot(H, V), 0.0));
    float G2 = smithUncorrelatedGeometry(V, L, rough);
    float G1 = smithShadowing(V, rough);
    brdf = F * G2 / G1;

    vec3 specdir = quaternionRotate(L, vec4(-q.xyz, q.w));
    vec3 diffusedir = cosineDir(normal, rng);

    float albchance = (1.0 - metal) * (1.0 - dot(fresnel(r, g, max(dot(normal, view), 0.0)), vec3(1.0 / 3.0)));
    float specchance = dot(F, vec3(1.0 / 3.0));
    if (randF(rng) <= specchance && metal != 1.0) {
        brdf /= specchance;
        return specdir;
    } else if (metal == 1.0) {
        return specdir;
    } else {
        brdf = (1.0 - metal) * (1.0 - fresnel(r, g, max(dot(normal, view), 0.0))) * alb / (1.0 - specchance);
        return diffusedir;
    }

    return specdir;
}

const float far = 1000.0;
#define SKYBOX

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    uint rng = uint(uint(fragCoord.x) * uint(1973) + uint(fragCoord.y) * uint(9277) + uint(iFrame) * uint(26699)) | uint(1);

    vec2 uv = (fragCoord / iResolution.xy) * 2.0 - 1.0;
    uv.x *= iResolution.x / iResolution.y;

    vec2 m = (iMouse.xy / iResolution.xy) * 2.0 - 1.0;
    m.x *= iResolution.x / iResolution.y;

    float fov = 90.0;
	vec3 ro = vec3(0.0, 0.0, -2.0);
    float camdist = 1.0 / tan(fov * 0.5 * pi / 180.0);
    vec3 rt = vec3(uv, camdist) + ro;
	vec3 rd = normalize(rt - ro);
	vec3 col;

    vec4 lastcol = texture(iChannel0, fragCoord / iResolution.xy);
    float temp = lastcol.w;

    if (iFrame == 0 || iMouse.z > 0.0) {
        lastcol = vec4(0.0);
        temp = 0.0;
    }

    info hit;
    hit.dist = far;

    bool h = iSphere(ro, rd, hit, vec4(0.0, 0.0, 0.0, 1.0));

    int samples = 1000;
    float rough = 0.1;
    rough *= rough;

    vec3 r = vec3(0.098,0.129,0.090); //F0 essentially
    vec3 g = vec3(0.000,1.000,0.533); // fresnel edgetint
    vec3 alb = vec3(1.000,0.000,0.000);
    float metal = 0.0;

    for (int i = 0; i < samples - min(iFrame, 0); i++) {
        if (fragCoord.x > iResolution.x / 2.0) {
            vec3 dir = hemiDir(hit.norm, rng);
            vec3 brdf = brdf(alb, rough, metal, r, g, hit.norm, -rd, dir) * 2.0 * pi;
            vec3 sky = texture(iChannel1, dir).rgb;
            #ifndef SKYBOX
            sky = vec3(0.8);
            #endif
            if (dot(dir, hit.norm) > 0.0) {
                col += sky * brdf;
                continue;
            }
        } else {
            vec3 brdf;
            vec3 dir = sampleSpecular(alb, rough, metal, r, g, hit.norm, -rd, rng, brdf);
            vec3 sky = texture(iChannel1, dir).rgb;
            #ifndef SKYBOX
            sky = vec3(0.8);
            #endif
            if (dot(dir, hit.norm) > 0.0) {
                col += sky * brdf;
                continue;
            }
        }
    }
    col /= float(samples);

    if (!h) col = texture(iChannel1, rd).rgb;
    #ifndef SKYBOX
    if (!h) col = vec3(0.8);
    #endif

    col += lastcol.rgb;
    temp += 1.0;

	fragColor = vec4(col, temp);
}
